def cta():return '<section class="cta"><div class="container"><div><h2>Let’s get your project flowing.</h2><p>From a small repair to a complete installation. Tell us what you need.</p></div>'+button('Get in touch','Contact.html','light')+'</div></section>'
def header(current,prefix):
 links=[('Home','index.html'),('Services','index.html#services'),('About','index.html#about'),('Our work','Our-Work.html'),('Contact','Contact.html')]
 nav=''.join(f'<a href="{prefix}{href}"'+(' aria-current="page"' if label==current else '')+f'>{label}</a>' for label,href in links)
 return f'''<a class="skip" href="#main">Skip to content</a><div class="topbar"><div class="container"><span>Plumbing, heating &amp; gas specialists across London</span><span>Need help? <a href="tel:+447838628381">{PHONE}</a></span></div></div><header class="site-header"><div class="container header-inner"><a class="brand" href="{prefix}index.html" aria-label="AM Plumbing home"><img src="{prefix}images/brand/am-plumbing-logo-wide.png" width="2172" height="724" alt="AM Plumbing &amp; Heating"></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu</button><nav class="nav" id="navigation" aria-label="Main navigation">{nav}{button('Get a quote',prefix+'Contact.html')}</nav></div></header>'''
