def write_page(filename,title,description,body,current='',prefix=''):
 canonical='https://amplumbing.uk/'+('' if filename=='index.html' else filename)
 output=f'''<!DOCTYPE html>
<html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#0c253b"><title>{escape(title)} | AM Plumbing &amp; Heating</title><meta name="description" content="{escape(description)}"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title)} | AM Plumbing &amp; Heating"><meta property="og:description" content="{escape(description)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://amplumbing.uk/images/projects/WA0032.webp"><link rel="icon" href="{prefix}images/brand/favicon.png" type="image/png" sizes="1254x1254"><link rel="apple-touch-icon" href="{prefix}images/brand/am-social-profile.png"><link rel="stylesheet" href="{prefix}site.css"><script src="{prefix}site.js" defer></script></head><body><noscript><style>@media(max-width:800px){{.header-inner{{flex-wrap:wrap;padding-bottom:15px}}.nav{{display:flex;position:static;flex-wrap:wrap;padding:0;border:0;box-shadow:none}}.menu-toggle{{display:none}}}}</style></noscript>{header(current,prefix)}<main id="main">{body}</main>{footer(prefix)}</body></html>'''
 (ROOT/filename).write_text(output,encoding='utf-8')
